using System;
using Framework.AI.Memory;
using Framework.AI.Perception;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// 認識記憶と空間記憶の基本機能を検証する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class AgentMemoryTest : MonoBehaviour
    {
        [Header("テスト設定")]
        [SerializeField]
        [Tooltip("開始時にすべてのテストを実行する。")]
        private bool runTestsOnStart = true;

        [Header("テスト結果")]
        [SerializeField]
        [Tooltip("成功したテスト件数。")]
        private int passedCount;

        [SerializeField]
        [Tooltip("失敗したテスト件数。")]
        private int failedCount;

        /// <summary>
        /// 予定されているテスト件数。
        /// </summary>
        private const int ExpectedTestCount = 40;

        /// <summary>
        /// 開始時のテスト実行を制御する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// すべての記憶システムのテストを実行する。
        /// </summary>
        [ContextMenu("すべてのテストを実行")]
        public void RunAllTests()
        {
            passedCount = 0;
            failedCount = 0;

            try
            {
                TestRemember();
                TestUpdateMemory();
                TestConfidence();
                TestForgetting();
                TestSpatialMemory();
                TestUnvisitedScore();
                TestIndependence();
                TestInvalidInput();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }

            Debug.Log(
                $"【AgentMemory テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}\n" +
                (failedCount == 0 &&
                 passedCount == ExpectedTestCount
                    ? "すべてのテストに成功しました。"
                    : "失敗または未実行のテストを確認してください。"),
                this);
        }

        /// <summary>
        /// テスト用の認識情報を生成する。
        /// </summary>
        /// <param name="sourceId">認識対象の識別子</param>
        /// <param name="position">認識位置</param>
        /// <param name="timestamp">認識時刻。単位は秒</param>
        /// <param name="confidence">認識時の信頼度</param>
        /// <returns>生成した認識情報</returns>
        private PerceptionStimulus<Vector2Int> CreateStimulus(
            Guid sourceId,
            Vector2Int position,
            double timestamp,
            float confidence = 1f)
        {
            return new PerceptionStimulus<Vector2Int>(
                sourceId,
                PerceptionType.Sight,
                position,
                confidence,
                timestamp);
        }

        /// <summary>
        /// 認識情報の保存を検証する。
        /// </summary>
        private void TestRemember()
        {
            var memory =
                new PerceptionMemory<Vector2Int>(10d);

            Guid sourceId = Guid.NewGuid();

            var position = new Vector2Int(3, 4);

            bool initialPassed =
                memory.Count == 0 &&
                memory.RetentionDuration == 10d;
            Debug.Assert(initialPassed, "認識記憶の初期状態", this);
            Check(initialPassed, "認識記憶の初期状態");

            bool rememberPassed =
                memory.Remember(
                    CreateStimulus(sourceId, position, 5d)) &&
                memory.Count == 1;
            Debug.Assert(rememberPassed, "認識情報の保存", this);
            Check(rememberPassed, "認識情報の保存");

            bool retrievePassed =
                memory.TryGetLastObservation(
                    sourceId,
                    out var stored) &&
                stored.Position == position &&
                stored.Timestamp == 5d;
            Debug.Assert(retrievePassed, "保存された認識情報の取得", this);
            Check(retrievePassed, "保存された認識情報の取得");

            bool invalidPassed =
                !memory.Remember(
                    default(PerceptionStimulus<Vector2Int>));
            Debug.Assert(invalidPassed, "無効な認識情報の拒否", this);
            Check(invalidPassed, "無効な認識情報の拒否");

            bool unknownPassed =
                !memory.Remember(
                    CreateStimulus(
                        Guid.Empty, position, 5d));
            Debug.Assert(unknownPassed, "対象不明の認識情報の拒否", this);
            Check(unknownPassed, "対象不明の認識情報の拒否");

            bool zeroPassed =
                !memory.Remember(
                    CreateStimulus(
                        Guid.NewGuid(), position, 5d, 0f)) &&
                memory.Count == 1;
            Debug.Assert(zeroPassed, "信頼度0の認識情報の拒否", this);
            Check(zeroPassed, "信頼度0の認識情報の拒否");
        }

        /// <summary>
        /// 認識情報の更新と時刻の優先順位を検証する。
        /// </summary>
        private void TestUpdateMemory()
        {
            var memory =
                new PerceptionMemory<Vector2Int>();

            Guid sourceId = Guid.NewGuid();

            var first = new Vector2Int(1, 1);
            var second = new Vector2Int(3, 3);
            var third = new Vector2Int(5, 5);

            memory.Remember(
                CreateStimulus(sourceId, first, 5d));

            bool newerPassed =
                memory.Remember(
                    CreateStimulus(
                        sourceId, second, 6d, 0.5f)) &&
                memory.TryGetLastObservation(
                    sourceId, out var updated) &&
                updated.Position == second &&
                memory.Count == 1;
            Debug.Assert(newerPassed, "新しい認識情報による更新", this);
            Check(newerPassed, "新しい認識情報による更新");

            bool olderPassed =
                !memory.Remember(
                    CreateStimulus(sourceId, first, 4d));
            Debug.Assert(olderPassed, "古い認識情報の拒否", this);
            Check(olderPassed, "古い認識情報の拒否");

            bool weakerPassed =
                !memory.Remember(
                    CreateStimulus(
                        sourceId, third, 6d, 0.2f));
            Debug.Assert(weakerPassed, "同時刻の低信頼度情報の拒否", this);
            Check(weakerPassed, "同時刻の低信頼度情報の拒否");

            bool strongerPassed =
                memory.Remember(
                    CreateStimulus(
                        sourceId, third, 6d, 0.9f)) &&
                memory.TryGetLastObservation(
                    sourceId, out var stronger) &&
                stronger.Position == third;
            Debug.Assert(strongerPassed, "同時刻の高信頼度情報の優先", this);
            Check(strongerPassed, "同時刻の高信頼度情報の優先");

            Guid otherId = Guid.NewGuid();

            bool multiplePassed =
                memory.Remember(
                    CreateStimulus(otherId, first, 7d)) &&
                memory.Count == 2;
            Debug.Assert(multiplePassed, "複数対象の記憶", this);
            Check(multiplePassed, "複数対象の記憶");
        }

        /// <summary>
        /// 時間経過による記憶信頼度の減衰を検証する。
        /// </summary>
        private void TestConfidence()
        {
            var memory =
                new PerceptionMemory<Vector2Int>(10d);

            Guid sourceId = Guid.NewGuid();

            var position = new Vector2Int(2, 3);

            memory.Remember(
                CreateStimulus(
                    sourceId, position, 5d, 0.8f));

            bool initialPassed =
                Mathf.Approximately(
                    memory.GetConfidence(sourceId, 5d),
                    0.8f);
            Debug.Assert(initialPassed, "認識直後の記憶信頼度", this);
            Check(initialPassed, "認識直後の記憶信頼度");

            bool halfPassed =
                Mathf.Approximately(
                    memory.GetConfidence(sourceId, 10d),
                    0.4f);
            Debug.Assert(halfPassed, "経過時間による信頼度減衰", this);
            Check(halfPassed, "経過時間による信頼度減衰");

            bool recallPassed =
                memory.TryRecall(
                    sourceId,
                    10d,
                    out var recalled,
                    out float confidence) &&
                recalled.Position == position &&
                recalled.Confidence == 0.8f &&
                Mathf.Approximately(confidence, 0.4f);
            Debug.Assert(recallPassed, "元の認識情報と減衰値の分離", this);
            Check(recallPassed, "元の認識情報と減衰値の分離");

            bool expiredPassed =
                !memory.TryRecall(
                    sourceId,
                    15d,
                    out var expired,
                    out float expiredConfidence) &&
                !expired.IsValid &&
                expiredConfidence == 0f;
            Debug.Assert(expiredPassed, "記憶保持期限の境界", this);
            Check(expiredPassed, "記憶保持期限の境界");

            bool futurePassed =
                !memory.TryRecall(
                    sourceId, 4d, out _, out _) &&
                memory.GetConfidence(sourceId, 4d) == 0f;
            Debug.Assert(futurePassed, "未来の認識情報の取得抑止", this);
            Check(futurePassed, "未来の認識情報の取得抑止");

            memory.SetRetentionDuration(20d);

            bool durationPassed =
                memory.RetentionDuration == 20d &&
                Mathf.Approximately(
                    memory.GetConfidence(sourceId, 15d),
                    0.4f);
            Debug.Assert(durationPassed, "記憶保持時間の変更反映", this);
            Check(durationPassed, "記憶保持時間の変更反映");
        }

        /// <summary>
        /// 記憶の期限切れと削除処理を検証する。
        /// </summary>
        private void TestForgetting()
        {
            var memory =
                new PerceptionMemory<Vector2Int>(10d);

            Guid firstId = Guid.NewGuid();
            Guid secondId = Guid.NewGuid();

            memory.Remember(
                CreateStimulus(
                    firstId, Vector2Int.zero, 0d));

            memory.Remember(
                CreateStimulus(
                    secondId, Vector2Int.one, 8d));

            bool storedPassed =
                memory.GetConfidence(firstId, 10d) == 0f &&
                memory.TryGetLastObservation(
                    firstId, out _) &&
                memory.Count == 2;
            Debug.Assert(storedPassed, "期限切れ記憶の物理的保持", this);
            Check(storedPassed, "期限切れ記憶の物理的保持");

            bool removePassed =
                memory.RemoveExpired(10d) == 1 &&
                memory.Count == 1 &&
                !memory.TryGetLastObservation(
                    firstId, out _);
            Debug.Assert(removePassed, "期限切れ記憶の削除", this);
            Check(removePassed, "期限切れ記憶の削除");

            bool remainingPassed =
                memory.TryRecall(
                    secondId, 10d, out _, out _);
            Debug.Assert(remainingPassed, "有効な記憶の維持", this);
            Check(remainingPassed, "有効な記憶の維持");

            bool forgetPassed =
                memory.Forget(secondId) &&
                !memory.Forget(secondId) &&
                memory.Count == 0;
            Debug.Assert(forgetPassed, "指定対象の記憶削除", this);
            Check(forgetPassed, "指定対象の記憶削除");

            memory.Remember(
                CreateStimulus(
                    firstId, Vector2Int.zero, 20d));

            memory.Clear();

            bool clearPassed = memory.Count == 0;
            Debug.Assert(clearPassed, "すべての認識記憶の削除", this);
            Check(clearPassed, "すべての認識記憶の削除");
        }

        /// <summary>
        /// 空間記憶の訪問記録を検証する。
        /// </summary>
        private void TestSpatialMemory()
        {
            var memory =
                new SpatialMemory<Vector2Int>();

            var first = new Vector2Int(1, 1);
            var second = new Vector2Int(2, 1);

            bool initialPassed =
                memory.VisitedPositionCount == 0 &&
                !memory.HasVisited(first) &&
                memory.GetVisitCount(first) == 0;
            Debug.Assert(initialPassed, "空間記憶の初期状態", this);
            Check(initialPassed, "空間記憶の初期状態");

            bool visitPassed =
                memory.RecordVisit(first, 5d) &&
                memory.TryGetEntry(first, out var entry) &&
                entry.IsVisited &&
                entry.VisitCount == 1 &&
                entry.FirstVisitedTime == 5d &&
                entry.LastVisitedTime == 5d;
            Debug.Assert(visitPassed, "初回訪問の記録", this);
            Check(visitPassed, "初回訪問の記録");

            bool revisitPassed =
                memory.RecordVisit(first, 10d) &&
                memory.TryGetEntry(first, out var updated) &&
                updated.VisitCount == 2 &&
                updated.FirstVisitedTime == 5d &&
                updated.LastVisitedTime == 10d;
            Debug.Assert(revisitPassed, "再訪問の記録", this);
            Check(revisitPassed, "再訪問の記録");

            bool duplicatePassed =
                !memory.RecordVisit(first, 10d) &&
                !memory.RecordVisit(first, 8d) &&
                memory.GetVisitCount(first) == 2;
            Debug.Assert(duplicatePassed, "重複訪問と古い訪問の拒否", this);
            Check(duplicatePassed, "重複訪問と古い訪問の拒否");

            bool multiplePassed =
                memory.RecordVisit(second, 12d) &&
                memory.VisitedPositionCount == 2 &&
                memory.GetVisitCount(second) == 1;
            Debug.Assert(multiplePassed, "複数地点の訪問記録", this);
            Check(multiplePassed, "複数地点の訪問記録");

            bool forgotten =
                memory.Forget(first) &&
                !memory.HasVisited(first) &&
                !memory.Forget(first);

            memory.Clear();

            bool clearPassed =
                forgotten &&
                memory.VisitedPositionCount == 0;
            Debug.Assert(clearPassed, "訪問記録の個別削除と全削除", this);
            Check(clearPassed, "訪問記録の個別削除と全削除");
        }

        /// <summary>
        /// 未訪問度と経過時間の評価を検証する。
        /// </summary>
        private void TestUnvisitedScore()
        {
            var memory =
                new SpatialMemory<Vector2Int>();

            var position = new Vector2Int(1, 1);

            bool unvisitedPassed =
                double.IsPositiveInfinity(
                    memory.GetTimeSinceLastVisit(
                        position, 5d)) &&
                memory.GetUnvisitedScore(
                    position, 5d, 10d) == 1f;
            Debug.Assert(unvisitedPassed, "未訪問地点の最大評価", this);
            Check(unvisitedPassed, "未訪問地点の最大評価");

            memory.RecordVisit(position, 5d);

            bool recentPassed =
                memory.GetUnvisitedScore(
                    position, 5d, 10d) == 0f;
            Debug.Assert(recentPassed, "訪問直後の最小評価", this);
            Check(recentPassed, "訪問直後の最小評価");

            bool elapsedPassed =
                memory.GetTimeSinceLastVisit(
                    position, 10d) == 5d &&
                Mathf.Approximately(
                    memory.GetUnvisitedScore(
                        position, 10d, 10d),
                    0.5f);
            Debug.Assert(elapsedPassed, "経過時間による未訪問度上昇", this);
            Check(elapsedPassed, "経過時間による未訪問度上昇");

            bool maximumPassed =
                memory.GetUnvisitedScore(
                    position, 15d, 10d) == 1f &&
                memory.GetUnvisitedScore(
                    position, 100d, 10d) == 1f;
            Debug.Assert(maximumPassed, "未訪問度の上限", this);
            Check(maximumPassed, "未訪問度の上限");

            bool earlierPassed =
                memory.GetTimeSinceLastVisit(
                    position, 4d) == 0d &&
                memory.GetUnvisitedScore(
                    position, 4d, 10d) == 0f;
            Debug.Assert(earlierPassed, "負の経過時間の防止", this);
            Check(earlierPassed, "負の経過時間の防止");
        }

        /// <summary>
        /// 個体ごとの記憶の独立性を検証する。
        /// </summary>
        private void TestIndependence()
        {
            var first =
                new PerceptionMemory<Vector2Int>();

            var second =
                new PerceptionMemory<Vector2Int>();

            Guid sourceId = Guid.NewGuid();

            first.Remember(
                CreateStimulus(
                    sourceId, Vector2Int.zero, 0d));

            bool perceptionPassed =
                first.Count == 1 &&
                second.Count == 0 &&
                !second.TryRecall(
                    sourceId, 0d, out _, out _);
            Debug.Assert(perceptionPassed, "認識記憶の個体別独立性", this);
            Check(perceptionPassed, "認識記憶の個体別独立性");

            var firstSpatial =
                new SpatialMemory<Vector2Int>();

            var secondSpatial =
                new SpatialMemory<Vector2Int>();

            firstSpatial.RecordVisit(
                Vector2Int.zero, 0d);

            bool spatialPassed =
                firstSpatial.HasVisited(Vector2Int.zero) &&
                !secondSpatial.HasVisited(Vector2Int.zero);
            Debug.Assert(spatialPassed, "空間記憶の個体別独立性", this);
            Check(spatialPassed, "空間記憶の個体別独立性");
        }

        /// <summary>
        /// 不正な設定値や入力値の拒否を検証する。
        /// </summary>
        private void TestInvalidInput()
        {
            bool durationPassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    new PerceptionMemory<Vector2Int>(0d);
                });
            Debug.Assert(durationPassed, "不正記憶保持時間の拒否", this);
            Check(durationPassed, "不正記憶保持時間の拒否");

            var perception =
                new PerceptionMemory<Vector2Int>();

            bool timePassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    perception.GetConfidence(
                        Guid.NewGuid(), double.NaN);
                });
            Debug.Assert(timePassed, "不正認識時刻の拒否", this);
            Check(timePassed, "不正認識時刻の拒否");

            var spatial =
                new SpatialMemory<Vector2Int>();

            bool visitTimePassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    spatial.RecordVisit(
                        Vector2Int.zero, -1d);
                });
            Debug.Assert(visitTimePassed, "不正訪問時刻の拒否", this);
            Check(visitTimePassed, "不正訪問時刻の拒否");

            bool scorePassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    spatial.GetUnvisitedScore(
                        Vector2Int.zero, 0d, 0d);
                });
            Debug.Assert(scorePassed, "不正未訪問度設定の拒否", this);
            Check(scorePassed, "不正未訪問度設定の拒否");

            bool entryPassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    new SpatialMemoryEntry(5d, 3d, 1);
                });
            Debug.Assert(entryPassed, "不正訪問記録の拒否", this);
            Check(entryPassed, "不正訪問記録の拒否");
        }

        /// <summary>
        /// 指定された処理が期待する例外を発生させるか検証する。
        /// </summary>
        /// <typeparam name="TException">期待する例外型</typeparam>
        /// <param name="action">検証対象の処理</param>
        /// <returns>期待する例外が発生した場合はtrue</returns>
        private bool Throws<TException>(Action action)
            where TException : Exception
        {
            try
            {
                action();
            }
            catch (Exception exception)
            {
                if (exception.GetType() == typeof(TException))
                {
                    return true;
                }

                throw;
            }

            return false;
        }

        /// <summary>
        /// 個別のテスト結果を出力し、結果を集計する。
        /// </summary>
        /// <param name="passed">テストの成功判定</param>
        /// <param name="testName">テスト名</param>
        private void Check(bool passed, string testName)
        {
            if (passed)
            {
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"【失敗】{testName}",
                    this);
            }
        }
    }
}
